// test_crate_loading.rs - Test suite for crate loading system
// Generated by step4_bootstrap - Crate Integration System

use split_decls_genesis::{
    mkcrate, mkdeps, mkbootstrap_deps, discover_available_crates, 
    CrateInfo, load_crate_source, extract_declarations, extract_names
};

fn main() -> anyhow::Result<()> {
    println!("🧬 Testing crate loading system...");
    
    // Discover available crates
    let available = discover_available_crates()?;
    println!("✅ Found {} available crates", available.len());
    println!("📦 Sample crates: {:?}", &available[..5.min(available.len())]);
    
    // Load bootstrap dependencies
    println!("\n🚀 Loading bootstrap dependencies...");
    let bootstrap_crates = mkbootstrap_deps!();
    println!("✅ Loaded {} bootstrap crates", bootstrap_crates.len());
    
    for crate_info in &bootstrap_crates {
        println!("📋 {}: {} declarations, {} names", 
                 crate_info.name, 
                 crate_info.declarations.len(),
                 crate_info.names.len());
    }
    
    // Test individual crate loading
    println!("\n🔍 Testing individual crate loading...");
    let crate_info = mkcrate!("anyhow");
    println!("✅ Loaded anyhow crate");
    println!("📝 Sample declarations: {:?}", &crate_info.declarations[..3.min(crate_info.declarations.len())]);
    println!("🏷️  Sample names: {:?}", &crate_info.names[..3.min(crate_info.names.len())]);
    
    println!("\n🎉 Crate loading system test complete!");
    Ok(())
}
